pub fn craft_recipe(item_id: u64) -> Option<CraftRecipe> {
    let mut lo = 0usize;
    let mut hi = CRAFT_RECIPES.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let r = CRAFT_RECIPES[mid];
        if r.item_id < item_id { lo = mid + 1; }
        else if r.item_id > item_id { hi = mid; }
        else { return Some(r); }
    }
    None
}

pub fn skill_label(skill: u8) -> Option<&'static str> {
    match skill {
        1 => Some("smithing"),
        2 => Some("woodworking"),
        3 => Some("leathercraft"),
        4 => Some("clothcraft"),
        5 => Some("bonecraft"),
        6 => Some("goldsmithing"),
        7 => Some("alchemy"),
        8 => Some("cooking"),
        _ => None,
    }
}
